function createAccountClient(previous?: QueryClient) {
  let retired = false;
  const cache = new MutationCache();
  const build = cache.build.bind(cache);
  cache.build = ((...args: Parameters<MutationCache["build"]>) => {
    const mutation = build(...args);
    const setOptions = mutation.setOptions.bind(mutation);
    mutation.setOptions = options => setOptions(retired ? { ...options,
      mutationFn: async () => { throw new ApiSessionChangedError(); },
      onSuccess: undefined, onError: undefined, onSettled: undefined,
    } : options);
    const execute = mutation.execute.bind(mutation);
    mutation.execute = async variables => {
      if (retired) throw new ApiSessionChangedError();
      try {
        const result = await execute(variables);
        if (retired) throw new ApiSessionChangedError();
        return result;
      } catch (error) {
        if (retired) throw new ApiSessionChangedError();
        throw error;
      }
    };
    return mutation;
  }) as MutationCache["build"];
